"""Independent raw metadata and reparse oracle on self-generated bytes only."""
import importlib.util
from pathlib import Path
import struct
import unittest

spec = importlib.util.spec_from_file_location('wim_extra_oracle', Path(__file__).parents[1]/'minios/wim_extra_oracle.py')
m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)


def reparse(tag=0xa0000003):
    sub, printable = '\\??\\D:\\Users\0'.encode('utf-16le'), 'D:\\Users\0'.encode('utf-16le')
    head = struct.pack('<HHHH', 0, len(sub)-2, len(sub), len(printable)-2)
    if tag == 0xa000000c: head += struct.pack('<I', 0)
    return head + sub + printable


def metadata():
    data=bytearray(512);struct.pack_into('<II',data,0,8,0)
    struct.pack_into('<QIIQ',data,8,104,0x10,0xffffffff,120)
    long='long filename.txt'.encode('utf-16le');short='LONGFI~1.TXT'.encode('utf-16le')
    end=m.align(102+len(long)+2+len(short)+2)
    struct.pack_into('<QII',data,120,end+72,0x20,0xffffffff)
    struct.pack_into('<HH',data,120+98,len(short),len(long))
    data[222:222+len(long)]=long
    start=222+len(long)+2;data[start:start+len(short)]=short
    struct.pack_into('<II',data,120+end,1,64)
    data[120+end+8:120+end+72]=bytes(range(1,65))
    return data


class Extras(unittest.TestCase):
    def test_destination_rewrites_both_names_but_preserves_source(self):
        for tag in (0xa0000003,0xa000000c):
            source=reparse(tag)
            actual=m.corrected_reparse(source,tag,0,0x80,'E')
            self.assertIn('\\??\\E:\\Users'.encode('utf-16le'),actual)
            self.assertIn('E:\\Users'.encode('utf-16le'),actual)
            self.assertEqual(source,reparse(tag))

    def test_not_fixed_relative_and_header_disabled_are_byte_exact(self):
        source=reparse()
        self.assertEqual(source,m.corrected_reparse(source,0xa0000003,1,0x80,'C'))
        self.assertEqual(source,m.corrected_reparse(source,0xa0000003,0,0,'C'))
        relative=bytearray(reparse(0xa000000c));struct.pack_into('<I',relative,8,1)
        self.assertEqual(relative,m.corrected_reparse(relative,0xa000000c,0,0x80,'C'))

    def test_invalid_ranges_and_drive_are_refused(self):
        data=bytearray(reparse());struct.pack_into('<H',data,0,65535)
        with self.assertRaises(ValueError):m.corrected_reparse(data,0xa0000003,0,0x80,'C')
        with self.assertRaises(ValueError):m.corrected_reparse(reparse(),0xa0000003,0,0x80,'1')

    def archive(self,data):
        value=m.Archive.__new__(m.Archive)
        value.metadata=[(None,None)];value.resource=lambda *_:bytes(data);value.flags=0x80
        return value

    def test_raw_short_name_and_object_id_are_independent_of_writer(self):
        rows=list(self.archive(metadata()).extras(1))
        self.assertEqual([r['path'] for r in rows],['','long filename.txt'])
        self.assertEqual(rows[1]['short_name'],'LONGFI~1.TXT')
        self.assertEqual(rows[1]['tagged'][0]['type'],1)
        self.assertEqual(rows[1]['tagged'][0]['hex'],bytes(range(1,65)).hex())

    def test_tagged_length_and_subtree_cycles_are_refused(self):
        data=metadata();end=m.align(102+len('long filename.txt')*2+2+len('LONGFI~1.TXT')*2+2)
        struct.pack_into('<I',data,120+end+4,65536)
        with self.assertRaises(ValueError):list(self.archive(data).extras(1))
        data=metadata();struct.pack_into('<Q',data,120+16,120)
        with self.assertRaises(ValueError):list(self.archive(data).extras(1))


if __name__=='__main__':unittest.main()
